    if (!xmqcli_inset(xmqcli_set_18, 1, xmqcli_ascii_18, xmqcli_peek(p, p->pos))) return xmqcli_fail(p, "grammar", "'x'");
    xmqcli_char(p, elem, attr, p->in[p->pos]);
